const sv=require('../app/src/main/assets/tcg-classic-paradox-rift'),data=require('../app/src/main/assets/tcg-classic-battle-data'),core=require('../app/src/main/assets/tcgp-battle-core'),fx=require('../app/src/main/assets/tcgp-battle-effects'),builder=require('../app/src/main/assets/tcg-classic-deck-builder'),opp=require('../app/src/main/assets/tcg-classic-opponents'),picker=require('../app/src/main/assets/tcg-classic-set-picker');
const source=require('../docs/SV4_CANONICAL_SOURCE.json'),raw=require('../data/classic/sv4-print-compact.json');
const codes={Grass:'G',Fire:'R',Water:'W',Lightning:'L',Psychic:'P',Fighting:'F',Darkness:'D',Metal:'M',Colorless:'C',Dragon:'N'};
test('Paradox Rift stage 18 exact registered subset and explicit remaining coverage',()=>{
 assert.equal(crypto.createHash('sha256').update(fs.readFileSync(require.resolve('../data/classic/sv4-print-compact.json'))).digest('hex'),source.compactSha256);
 assert.equal(sv.CARDS.length,249);assert.equal(sv.coverage().total,266);assert.equal(sv.coverage().unregistered,17);assert.equal(sv.coverage().battleEnabled,249);assert.equal(sv.SET.complete,false);assert.equal(new Set(sv.CARDS.map(c=>c.id)).size,249);assert.equal(sv.cardById('sv4-17'),null);for(const [a,b] of [[165,235],[168,237],[173,242],[174,243]])assert.deepEqual(sv.cardById('sv4-'+a).effect,sv.cardById('sv4-'+b).effect);
 for(const p of raw){const c=sv.cardById(p.id);assert.equal(data.cardById(p.id),c);assert.deepEqual([c.name,c.number,c.rarity,c.kind,c.image,c.imageLarge],[p.name,p.number,p.rarity,p.kind,p.image,p.imageLarge]);assert.ok(c.deckEligible);
  if(c.kind==='pokemon'){assert.deepEqual([c.hp,c.types,c.evolvesFrom,c.retreat,c.weakness,c.resistance],[p.hp,p.types,p.evolvesFrom,p.retreat,p.weakness,p.resistance]);assert.deepEqual(c.attacks.map(a=>[a.name,a.cost,a.damageText||'',a.text]),p.attacks.map(a=>[a.name,a.cost.map(t=>codes[t]).join(''),a.damage,a.text]));for(const a of c.attacks){assert.ok(fx.supportsEffect(a.effect),c.id);assert.equal(a.effect.type==='noop',!a.text);}}
  else {assert.equal(c.text,p.rules[0]);assert.ok(fx.supportsEffect(c.effect));}
 }
 for(const [a,b] of [[44,190],[60,193],[62,195],[64,196],[88,198],[145,211],[149,212],[19,186]])assert.deepEqual(sv.cardById('sv4-'+a).attacks,sv.cardById('sv4-'+b).attacks);
});
test('Paradox Rift ownership, picker, standalone gate and mixed player/CPU selection',()=>{
 for(const ids of [builder.SET_IDS,opp.SETS]){assert.ok(ids.includes('sv4'));assert.match(picker.html({ids,selected:['sv4']}),/data-set-choice="sv4"/);}
 const owned=data.projectOwnedCards([{id:'library:sv4:001',quantity:2},{setId:'sv4',number:'1/182',quantity:1},{id:'sv4-17',quantity:4}]);assert.equal(owned.find(x=>x.gameplayId==='sv4-1').quantity,3);assert.ok(!owned.some(x=>x.gameplayId==='sv4-17'));
 const rows=data.CARDS.filter(c=>['sv4','sv3pt5'].includes(c.setId)&&c.battleEnabled&&c.deckEligible!==false).map(c=>({gameplayId:c.id,quantity:4}));
 assert.equal(builder.buildDeck(rows,{sets:['sv4']}).ok,false);assert.equal(opp.generate({sets:['sv4'],type:'Water',seed:3}).ok,false);
 const result=builder.buildDeck(rows,{sets:['sv4','sv3pt5'],types:['Water'],focusCardId:'sv4-43',randomSeed:7});assert.ok(result.ok,result.error);assert.ok(result.cards.includes('sv4-44'));assert.ok(result.cards.includes('sv4-43'));
 const generated=opp.generate({sets:['sv4','sv3pt5'],type:'Water',seed:3});assert.ok(generated.ok,generated.error);
});
const deck=[...Array(4).fill('sv1-30'),...Array(4).fill('sv1-32'),...Array(4).fill('sv1-33'),...Array(4).fill('sv1-36'),...Array(4).fill('sv1-188'),...Array(4).fill('sv1-180'),...Array(4).fill('sv1-189'),...Array(2).fill('sv1-194')];
function scene(side,id){const foe=side==='player'?'opponent':'player',s=core.createBattle({format:'classic',playerDeck:deck,opponentDeck:deck,seed:32,firstSide:side,playerEnergyTypes:['Grass','Fire','Water','Lightning','Fighting','Psychic'],opponentEnergyTypes:['Grass','Fire','Water','Lightning','Fighting','Psychic']});s.phase='battle';s.activeSide=side;s.turnNumber=8;for(const who of [side,foe]){const b=s.sides[who];b.turnCount=4;b.active=core.makePokemonSlot(who===side?id:'sv3pt5-6',1,who+'a');b.active.energy={Grass:4,Fire:4,Water:4,Lightning:4,Psychic:4,Fighting:4,Darkness:4,Metal:4};b.bench=[{...core.makePokemonSlot('sv3pt5-6',1,who+'b'),benchSlot:0}];}return {s,us:s.sides[side],them:s.sides[foe]};}
function attack(s,side,i=0){const a=core.legalActions(s,side).find(a=>a.type==='attack'&&a.attackIndex===i);assert.ok(a,JSON.stringify(core.legalActions(s,side)));core.applyAction(s,side,a);}
for(const side of ['player','opponent']){
 test(side+' Toedscool Absorb heals 20; Blitzle Wild Charge deals 20 recoil',()=>{let {s,us}=scene(side,'sv4-16');let a=us.active;a.damage=30;attack(s,side,1);assert.equal(a.damage,10);({s,us}=scene(side,'sv4-195'));a=us.active;attack(s,side,1);assert.equal(a.damage,20);});
 test(side+' Plusle alternate print counts actual damage counters',()=>{const {s,them}=scene(side,'sv4-193');const target=them.active;target.damage=30;attack(s,side);assert.equal(target.damage,70);});
 test(side+' Elekid zero-cost selected damage hits only chosen Bench',()=>{const {s,us,them}=scene(side,'sv4-59');us.active.energy={};const target=them.bench[0];const pick=core.legalActions(s,side).find(a=>a.type==='attack'&&a.target==='opponentBench'&&a.benchIndex===0);assert.ok(pick,JSON.stringify(core.legalActions(s,side)));core.applyAction(s,side,pick);assert.equal(target.damage,30);assert.equal(them.active.damage,0);});
 test(side+' Counter Catcher regular and gold print require Prize deficit and select opponent Bench',()=>{for(const id of ['sv4-160','sv4-264']){const {s,us,them}=scene(side,'sv4-1');us.hand=[{uid:'catcher',cardId:id}];us.prizes=[{uid:'p1',cardId:'sv4-1'},{uid:'p2',cardId:'sv4-1'}];them.prizes=[{uid:'p3',cardId:'sv4-1'},{uid:'p4',cardId:'sv4-1'}];const get=()=>core.legalActions(s,side).find(a=>a.type==='trainer'&&a.cardId===id);assert.equal(get(),undefined);them.prizes.pop();assert.ok(get());const target=them.bench[0];core.applyAction(s,side,get());const pick=core.legalActions(s,side).find(a=>a.choiceBenchIndex===0);assert.ok(pick);core.applyAction(s,side,pick);assert.equal(them.active,target);}});
 test(side+' Beach Court gold print shares Basic-only retreat reduction',()=>{const {s,us,them}=scene(side,'sv4-23');const foe=side==='player'?'opponent':'player';us.hand=[{uid:'court',cardId:'sv4-263'}];const a=core.legalActions(s,side).find(a=>a.type==='trainer'&&a.cardId==='sv4-263');assert.ok(a);core.applyAction(s,side,a);assert.equal(core.retreatCost(s,side),1);assert.equal(core.retreatCost(s,foe),2);});
}
