 test(side+' stage 2 Golisopod counts enemy hand, Ambipom counts own hand',()=>{for(const [id,i] of [['sv4-49',0],['sv4-146',1]]){const {s,us,them}=scene(side,id);them.active=core.makePokemonSlot('sv4-40',1,'neutral');const target=them.active;us.hand=[{uid:'own',cardId:'sv4-1'}];them.hand=[1,2,3].map(n=>({uid:'opp'+n,cardId:'sv4-1'}));attack(s,side,i);assert.equal(target.damage,id==='sv4-49'?60:20);}});
