test('stage 5 Ancient Future and lowercase ex metadata and alternate parity',()=>{for(const id of ['sv4-70','sv4-223','sv4-248']){const c=sv.cardById(id);assert.ok(c.future&&c.isEx&&c.ruleBox);assert.equal(c.prizeCards,2);}for(const id of ['sv4-107','sv4-203','sv4-163'])assert.equal(sv.cardById(id).ancient,true);for(const [a,b] of [[68,222],[70,248],[107,203],[135,230]])assert.deepEqual(sv.cardById('sv4-'+a).attacks,sv.cardById('sv4-'+b).attacks);});
